css:
.probstats-sim-container {
    padding: 28px;
    background: #0a0f1e;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e0e6f0;
}
.probstats-sim-container * { box-sizing: border-box; }

.probstats-sim-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-left: 4px solid #00ff88;
    padding: 20px 28px;
    margin-bottom: 24px;
    background: rgba(0,255,136,0.05);
    border-radius: 0 8px 8px 0;
}
.probstats-sim-brand { display: flex; align-items: center; gap: 14px; }
.probstats-sim-pulse {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: #00ff88;
    box-shadow: 0 0 12px #00ff88;
    animation: probstats-pulse 2s infinite;
}
@keyframes probstats-pulse {
    0%, 100% { opacity: 1; transform: scale(1); }
    50% { opacity: 0.4; transform: scale(0.85); }
}
.probstats-sim-header h1 {
    color: #00ff88;
    font-size: 1.3rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin: 0;
    font-weight: 700;
}
.probstats-sim-period-counter {
    font-family: 'SFMono-Regular', Menlo, Consolas, monospace;
    color: #00bfff;
    font-size: 0.9rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    padding: 8px 14px;
    border: 1px solid #1f2d3d;
    border-radius: 4px;
    background: #0d1321;
}

.probstats-sim-briefing-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-left: 3px solid #00bfff;
    border-radius: 8px;
    padding: 22px 26px;
    margin-bottom: 24px;
}
.probstats-sim-briefing-header {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 12px;
}
.probstats-sim-tag {
    background: #00bfff;
    color: #0a0f1e;
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.14em;
    padding: 4px 10px;
    border-radius: 3px;
}
.probstats-sim-briefing-card h2 {
    color: #e0e6f0;
    font-size: 1.15rem;
    font-weight: 600;
    margin: 0;
}
.probstats-sim-briefing-body {
    color: #a0a9b8;
    line-height: 1.65;
    font-size: 0.92rem;
}

.probstats-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
    gap: 16px;
    margin-bottom: 28px;
}
.probstats-sim-kpi-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 22px 20px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.25s ease, transform 0.2s ease;
}
.probstats-sim-kpi-card:hover {
    border-color: #00ff88;
    transform: translateY(-2px);
}
.probstats-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, #00ff88, #00bfff);
}
.probstats-sim-kpi-label {
    color: #6b7280;
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-bottom: 10px;
}
.probstats-sim-kpi-value {
    font-size: 1.75rem;
    font-weight: 700;
    color: #00ff88;
    font-family: 'SFMono-Regular', Menlo, Consolas, monospace;
    letter-spacing: -0.02em;
}

.probstats-sim-controls {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 24px 28px;
    margin-bottom: 22px;
}
.probstats-sim-controls h3 {
    color: #00bfff;
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin: 0 0 20px 0;
    font-weight: 600;
}
.probstats-sim-control-row {
    display: grid;
    grid-template-columns: 230px 1fr 60px;
    align-items: center;
    gap: 16px;
    margin-bottom: 14px;
}
.probstats-sim-control-row label {
    color: #a0a9b8;
    font-size: 0.85rem;
    font-weight: 500;
    margin: 0;
}
.probstats-sim-controls input[type="number"],
.probstats-sim-controls input[type="text"],
.probstats-sim-controls select {
    background: #0a0f1e;
    border: 1px solid #2d3f55;
    color: #e0e6f0;
    border-radius: 4px;
    padding: 9px 12px;
    width: 100%;
    font-family: inherit;
    font-size: 0.9rem;
}
.probstats-sim-controls input[type="range"] {
    background: #0a0f1e;
    border: 1px solid #2d3f55;
    width: 100%;
    height: 34px;
    padding: 0 10px;
    border-radius: 4px;
    accent-color: #00ff88;
}
.probstats-sim-controls select:focus,
.probstats-sim-controls input:focus {
    outline: none;
    border-color: #00ff88;
    box-shadow: 0 0 0 2px rgba(0,255,136,0.15);
}
.probstats-sim-controls select option {
    background: #111827;
    color: #e0e6f0;
}
.probstats-sim-controls #intensityValue {
    color: #00ff88;
    font-weight: 700;
    font-family: 'SFMono-Regular', Menlo, Consolas, monospace;
    text-align: center;
    background: #0a0f1e;
    border: 1px solid #1f2d3d;
    border-radius: 4px;
    padding: 8px 4px;
    font-size: 0.95rem;
}

.probstats-sim-action-row {
    display: flex;
    gap: 12px;
    margin-top: 22px;
    justify-content: flex-end;
    border-top: 1px solid #1f2d3d;
    padding-top: 20px;
}
.probstats-sim-action-row .btn {
    border-radius: 4px;
    font-weight: 600;
    letter-spacing: 0.06em;
    padding: 10px 24px;
    font-size: 0.88rem;
    text-transform: uppercase;
    transition: all 0.2s ease;
}
.probstats-sim-action-row .btn-primary {
    background: #00ff88;
    border-color: #00ff88;
    color: #0a0f1e;
}
.probstats-sim-action-row .btn-primary:hover,
.probstats-sim-action-row .btn-primary:focus {
    background: #00d974;
    border-color: #00d974;
    color: #0a0f1e;
    box-shadow: 0 0 16px rgba(0,255,136,0.45);
}
.probstats-sim-action-row .btn-outline-secondary {
    color: #a0a9b8;
    border-color: #2d3f55;
    background: transparent;
}
.probstats-sim-action-row .btn-outline-secondary:hover {
    color: #e0e6f0;
    background: #1f2d3d;
    border-color: #2d3f55;
}

.probstats-sim-hint {
    background: rgba(0,191,255,0.06);
    border: 1px solid rgba(0,191,255,0.25);
    border-radius: 6px;
    padding: 12px 18px;
    margin-bottom: 24px;
    color: #a0d8ff;
    font-size: 0.9rem;
    line-height: 1.5;
}
.probstats-sim-hint:empty { display: none; }

.probstats-sim-split {
    display: grid;
    grid-template-columns: 1.3fr 1fr;
    gap: 20px;
}
.probstats-sim-chart-card,
.probstats-sim-history-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px 22px;
}
.probstats-sim-chart-card h3,
.probstats-sim-history-card h3 {
    color: #00bfff;
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin: 0 0 14px 0;
    font-weight: 600;
}
.probstats-sim-chart-card { position: relative; }
.probstats-sim-chart-card canvas {
    max-height: 340px !important;
    height: 340px !important;
}

.probstats-sim-history-card { overflow-x: auto; }
.probstats-sim-history-card table {
    color: #e0e6f0;
    font-size: 0.82rem;
    margin: 0;
    width: 100%;
    background: transparent;
}
.probstats-sim-history-card table th {
    color: #6b7280;
    text-transform: uppercase;
    font-size: 0.65rem;
    letter-spacing: 0.1em;
    border-bottom: 1px solid #2d3f55;
    padding: 10px 8px;
    background: #0d1321;
    font-weight: 600;
}
.probstats-sim-history-card table td {
    padding: 10px 8px;
    border-color: #1f2d3d;
    color: #c9d1de;
}
.probstats-sim-history-card table tbody tr:hover {
    background: rgba(0,191,255,0.05);
}

@media (max-width: 900px) {
    .probstats-sim-split { grid-template-columns: 1fr; }
}
@media (max-width: 768px) {
    .probstats-sim-container { padding: 16px; }
    .probstats-sim-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 12px;
    }
    .probstats-sim-header h1 { font-size: 1.1rem; }
    .probstats-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); gap: 12px; }
    .probstats-sim-kpi-value { font-size: 1.35rem; }
    .probstats-sim-control-row {
        grid-template-columns: 1fr;
        gap: 8px;
    }
    .probstats-sim-action-row { flex-direction: column-reverse; }
    .probstats-sim-action-row .btn { width: 100%; }
}

/* EQIL 2026-10-28: contrast (AA), focus ring, reduced motion, briefing line breaks */
.probstats-sim-kpi-label,
.probstats-sim-history-card table th { color: #8f98a8; }
.probstats-sim-container select:focus-visible,
.probstats-sim-container input:focus-visible,
.probstats-sim-container button:focus-visible { outline: 3px solid #00bfff; outline-offset: 2px; }
.probstats-sim-briefing-body { white-space: pre-line; }
@media (prefers-reduced-motion: reduce) {
    .probstats-sim-pulse { animation: none; }
    .probstats-sim-container * { transition: none !important; }
}

