                { v: 'comprehensive', k: 'r4_p_comprehensive' },
                { v: 'external_audit', k: 'r4_p_external' }
            ],
            secondaryOptions: [
                { v: 'no_change', k: 'r4_s_no_change' },
                { v: 'peer_review', k: 'r4_s_peer' },
                { v: 'model_committee', k: 'r4_s_committee' },
                { v: 'board_oversight', k: 'r4_s_board' }
            ]
        }
    };

    var CORRECT_R1 = {
        rf1: 'lognormal',
        rf2: 'negbin',
        rf3: 'betabin',
        rf4: 'weibull',
        rf5: 'beta_inf',
        rf6: 'mc_10k'
    };

    var MAX_ROUNDS = 4;

    var FLAG_EXPOSURE = { rf1: 8500, rf2: 3200, rf3: 1800, rf4: 5600, rf5: 2100, rf6: 1600 }; // COP M, case Exhibit figures per red flag
    var SFC_FLAGS = { rf1: true, rf6: true }; // flags under SFC supervision (Circulars 018 and 031)
    var TIER_CUTS = { excellent: 85, good: 72, adequate: 58 };
    function plateau(v, lo, hi) {
        v = Number(v) || 0;
        if (v < lo) return Math.max(0.3, 1 - 0.08 * (lo - v));
        if (v > hi) return Math.max(0.3, 1 - 0.06 * (v - hi));
        return 1;
    }
    var TOTAL_EXPOSURE = 22120; // COP M — stated total exposure across all six red flags

    class DistributionExplorerAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'DataVista Distribution Explorer';
            this.version = '1.2.0';
            this._lastRenderedPeriod = 0;
            this._wired = false;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = this._defaultDomainState();
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    primary: 'rf1',
                    secondary: 'normal',
                    intensity: 5,
                    communication: 'controlled'
                };
            }
            var self = this;
            setTimeout(function() { self._updateBriefing(state); }, 0);
        }

        validateDecisions(decisions) {
            var p = document.getElementById('primaryChoice');
            var s = document.getElementById('secondaryChoice');
            var i = document.getElementById('intensityInput');
            var c = document.getElementById('communicationChoice');

            if (p) decisions.primary = p.value;
            if (s) decisions.secondary = s.value;
            if (i) decisions.intensity = parseInt(i.value, 10);
            if (c) decisions.communication = c.value;

            if (!decisions.primary || !decisions.secondary) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('decision_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.intensity || decisions.intensity < 1 || decisions.intensity > 10) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('intensity_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            return this._computeRound(state);
        }

        _computeRound(state) {
            var d = state.decisions;
            var round = state.currentPeriod;
            var ds = state.domainState;
            if (!ds.trace) ds.trace = { familyOK: null, flag: null, r2Gain: 0, auditPass: null, silentRounds: 0, earlyDisclosure: false, inflight: 0, rework: 0, revealed: false };
            var tr = ds.trace;

            var repDelta = 0;
            var exposureDelta = 0;
            var cashDelta = 0;
            var clientsDelta = 0;
            var diagnosisCorrect = false;
            var feedbackKey = 'fb_generic';
            var notes = [];
            var intensity = Number(d.intensity) || 0;

            /* Communication posture: costs and delayed effects (case: controlled release outperforms
               keep-internal on retention, and proactive disclosure before a fix invites an SFC referral) */
            var commRep = 0;
            if (d.communication === 'controlled') { commRep = 1; cashDelta -= 40; }
            else if (d.communication === 'proactive') {
                commRep = 1; cashDelta -= 60;
                if (round === 1) tr.earlyDisclosure = true;
            } else if (d.communication === 'internal') {
                if (round <= 2) { commRep = (round === 1) ? 1 : 0; tr.silentRounds++; }
                else { commRep = -4; clientsDelta -= 1; }
            }
            repDelta += commRep;

            if (round === 1) {
                var flag = d.primary;
                var flagExp = FLAG_EXPOSURE[flag] || 0;
                var expected = CORRECT_R1[flag];
                tr.flag = flag;
                var depthQ = plateau(intensity, 6, 8);
                cashDelta -= 30 * intensity;
                if (expected && expected === d.secondary) {
                    diagnosisCorrect = true;
                    tr.familyOK = true;
                    repDelta += 3;
                    exposureDelta += Math.round(0.35 * flagExp * depthQ);
                    feedbackKey = 'fb_r1_correct';
                } else {
                    tr.familyOK = false;
                    repDelta -= 2;
                    feedbackKey = 'fb_r1_wrong';
                }
                notes.push(feedbackKey);

            } else if (round === 2) {
                var fExp = FLAG_EXPOSURE[tr.flag] || 0;
                var share = 0;
                if (d.primary === 'rebuild') { share = tr.familyOK ? 0.55 : 0.2; repDelta += 3; cashDelta -= 420; }
                else if (d.primary === 'outsource') { share = tr.familyOK ? 0.45 : 0.2; repDelta += 2; cashDelta -= 720; }
                else if (d.primary === 'patch') { share = 0.25; repDelta += 1; cashDelta -= 120; }
                else if (d.primary === 'defer') { share = 0; repDelta -= 4; cashDelta -= 20; }
                var valQ = 0.4;
                if (d.secondary === 'full_battery') { valQ = 1.0; repDelta += 1; cashDelta -= 220; }
                else if (d.secondary === 'ks_ad') { valQ = 0.85; repDelta += 1; cashDelta -= 110; }
                else if (d.secondary === 'qq_only') { valQ = 0.6; cashDelta -= 50; }
                else if (d.secondary === 'none') { valQ = 0.4; repDelta -= 3; }
                cashDelta -= 50 * intensity;
                exposureDelta += Math.round(fExp * share * valQ * plateau(intensity, 6, 8));
                tr.r2Gain = exposureDelta;
                tr.r2Primary = d.primary;
                tr.auditPass = (d.primary === 'rebuild' || d.primary === 'outsource') && tr.familyOK === true &&
                    (d.secondary === 'full_battery' || d.secondary === 'ks_ad');
                feedbackKey = (d.primary === 'rebuild' && d.secondary === 'full_battery') ? 'fb_r2_best' : 'fb_r2_generic';
                notes.push(feedbackKey);

            } else if (round === 3) {
                /* The SFC shock lands first: audit of the remediated model, client discovery of any silence,
                   and the referral an early public disclosure invited */
                if (tr.r2Primary === 'defer') { repDelta -= 8; clientsDelta -= 2; notes.push('fb_audit_defer'); }
                else if (tr.auditPass) { notes.push('fb_audit_pass'); }
                else {
                    exposureDelta -= Math.round(tr.r2Gain * (tr.r2Primary === 'patch' ? 1 : 0.5));
                    repDelta -= 10; clientsDelta -= 2; notes.push('fb_audit_fail');
                }
                if (!SFC_FLAGS[tr.flag]) { repDelta -= 4; notes.push('fb_sfc_open'); }
                if (tr.silentRounds > 0 && !tr.revealed) {
                    repDelta -= 7 * tr.silentRounds; clientsDelta -= tr.silentRounds; tr.revealed = true;
                    notes.push('fb_silence_revealed');
                }
                if (tr.earlyDisclosure) { repDelta -= 6; notes.push('fb_referral'); }

                var pool = Math.max(0, TOTAL_EXPOSURE - (FLAG_EXPOSURE[tr.flag] || 0));
                var base = 0;
                if (d.primary === 'triage_top3') { base = 0.55; repDelta += 2; clientsDelta -= 1; cashDelta -= 150; }
                else if (d.primary === 'parallel_all') { base = 0.6; repDelta += 4; cashDelta -= 400; }
                else if (d.primary === 'serial') { base = 0.3; clientsDelta -= 2; cashDelta -= 100; }
                else if (d.primary === 'abandon_low') { base = 0.4; repDelta -= 6; clientsDelta -= 4; cashDelta += 100; }
                var conQ = 0.85;
                if (d.secondary === 'senior_limited') { conQ = 1.0; repDelta += 1; cashDelta -= 134; }
                else if (d.secondary === 'aggressive') { conQ = 1.15; repDelta += 1; cashDelta -= 700; }
                else if (d.secondary === 'no_contractors') { conQ = 0.85; }
                else if (d.secondary === 'contractor_only') { conQ = 0.7; repDelta -= 2; clientsDelta -= 1; cashDelta -= 900; }
                var weeks = 4 + (Math.max(1, Math.min(10, intensity)) - 1) * 38 / 9;
                cashDelta -= Math.round(7.2 * weeks);
                var coverage = Math.pow(weeks / 42, 0.8);
                var gain = Math.round(pool * base * conQ * coverage);
                exposureDelta += gain;
                tr.inflight = (d.primary === 'parallel_all') ? Math.round(gain * 0.65) : 0;
                tr.rework = (d.secondary === 'aggressive') ? Math.round(gain * 0.5) : 0;
                feedbackKey = (d.primary === 'triage_top3' && d.secondary === 'senior_limited') ? 'fb_r3_best' : 'fb_r3_generic';
                notes.push(feedbackKey);

            } else if (round === 4) {
                if (tr.inflight > 0) { exposureDelta -= tr.inflight; repDelta -= 6; clientsDelta -= 2; notes.push('fb_inflight_lost'); }
                if (tr.rework > 0) { exposureDelta -= tr.rework; repDelta -= 8; clientsDelta -= 2; notes.push('fb_onboarding_rework'); }
                var prevent = 0;
                if (d.primary === 'comprehensive') { prevent = 3300; repDelta += 2; cashDelta -= 500; }
                else if (d.primary === 'validation_std') { prevent = 2400; repDelta += 1; cashDelta -= 250; }
                else if (d.primary === 'external_audit') { prevent = 1500; cashDelta -= 900; }
                else if (d.primary === 'checklist') { prevent = 700; repDelta -= 2; cashDelta -= 60; }
                var govQ = 0.4;
                if (d.secondary === 'model_committee') { govQ = 1.0; repDelta += 3; cashDelta -= 200; }
                else if (d.secondary === 'board_oversight') { govQ = 0.9; repDelta += 2; cashDelta -= 300; }
                else if (d.secondary === 'peer_review') { govQ = 0.8; repDelta += 1; cashDelta -= 80; }
                else if (d.secondary === 'no_change') { govQ = 0.4; repDelta -= 5; clientsDelta -= 1; }
                cashDelta -= 40 * intensity;
                exposureDelta += Math.round(prevent * govQ * plateau(intensity, 6, 8));
                feedbackKey = (d.primary === 'comprehensive' && d.secondary === 'model_committee') ? 'fb_r4_best' : 'fb_r4_generic';
                notes.push(feedbackKey);
            }

            ds.reputation = Math.max(0, Math.min(100, ds.reputation + repDelta));
            ds.exposureMitigated = Math.max(0, Math.min(TOTAL_EXPOSURE, ds.exposureMitigated + exposureDelta));
            ds.cash = ds.cash + cashDelta;
            ds.clientsRetained = Math.max(0, Math.min(23, ds.clientsRetained + clientsDelta));
            if (diagnosisCorrect) ds.correctDiagnoses++;

            ds.reputationHistory.push(ds.reputation);
            ds.exposureHistory.push(ds.exposureMitigated);
            ds.cashHistory.push(ds.cash);
            ds.clientsHistory.push(ds.clientsRetained);

            var score = this._composite(ds);
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: score });
            ds.performanceTier = this._tierFor(score);

            /* Fallback render of the advanced round, guarded so it never adds one to the period;
               the period:submitted event is the primary path (see _wireFrameworkEvents) */
            var self = this;
            setTimeout(function() {
                if (!window.mySimulation || !window.mySimulation.state) return;
                var live = window.mySimulation.state.currentPeriod;
                if (typeof live === 'number' && live > self._lastRenderedPeriod && live <= MAX_ROUNDS) {
                    self._updateBriefing(window.mySimulation.state);
                }
            }, 300);

            return {
                period: state.currentPeriod,
                primary: d.primary,
                secondary: d.secondary,
                intensity: d.intensity,
                communication: d.communication,
                repDelta: repDelta,
                exposureDelta: exposureDelta,
                cashDelta: cashDelta,
                clientsDelta: clientsDelta,
                reputation: ds.reputation,
                exposureMitigated: ds.exposureMitigated,
                cash: ds.cash,
                clientsRetained: ds.clientsRetained,
                diagnosisCorrect: diagnosisCorrect,
                feedbackKey: feedbackKey,
                notes: notes,
                overallScore: score,
                score: score
            };
        }

        _composite(ds) {
            /* reputation 0-100, exposure mitigated and clients retained scaled to 0-100 by their own caps */
            var pfRep = ds.reputation;
            var pfExp = Math.min(100, 100 * ds.exposureMitigated / TOTAL_EXPOSURE);
            var pfClients = Math.min(100, 100 * ds.clientsRetained / 23);
            var s = Math.round(pfRep * 0.4 + pfExp * 0.4 + pfClients * 0.2);
            return Math.max(0, Math.min(100, s));
        }

        _tierFor(score) {
            if (score >= TIER_CUTS.excellent) return 'perf_excellent';
            if (score >= TIER_CUTS.good) return 'perf_good';
            if (score >= TIER_CUTS.adequate) return 'perf_adequate';
            return 'perf_beginner';
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod', function(v) { return Math.min(v, MAX_ROUNDS); });
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                function(v) { return 'COP ' + Math.round(v).toLocaleString() + 'M'; });
            uiManager.bind('reputationDisplay', 'domainState.reputation',
                function(v) { return Math.round(v) + ' / 100'; });
            uiManager.bind('exposureDisplay', 'domainState.exposureMitigated',
                function(v) { return 'COP ' + Math.round(v).toLocaleString() + 'M'; });
            uiManager.bind('clientsDisplay', 'domainState.clientsRetained',
                function(v) { return v + ' / 23'; });

            var slider = document.getElementById('intensityInput');
            var readout = document.getElementById('intensityValue');
            if (slider && readout) {
                slider.addEventListener('input', function() {
                    readout.textContent = slider.value;
                });
            }

            this._wireFrameworkEvents();
        }

        getChartConfig() {
            var t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : null;
            var L = function(k, fb) { var v = t ? t(k) : null; return (v && v !== k) ? v : fb; };
            return {
                crisisChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: L('chart_rep', 'Reputation'),
                                data: [],
                                borderColor: '#00ff88',
                                backgroundColor: 'rgba(0,255,136,0.12)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.3,
                                yAxisID: 'y',
                                pointBackgroundColor: '#00ff88',
                                pointRadius: 5
                            },
                            {
                                label: L('chart_exp', 'Exposure Mitigated (COP M)'),
                                data: [],
                                borderColor: '#00bfff',
                                backgroundColor: 'rgba(0,191,255,0.12)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.3,
                                yAxisID: 'y1',
                                pointBackgroundColor: '#00bfff',
                                pointRadius: 5
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        interaction: { mode: 'index', intersect: false },
                        plugins: {
                            legend: { labels: { color: '#e0e6f0', usePointStyle: true } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true,
                                max: 100,
                                position: 'left',
                                ticks: { color: '#e0e6f0' },
                                grid: { color: 'rgba(255,255,255,0.05)' },
                                title: { display: true, text: L('chart_rep_axis', 'Reputation (0-100)'), color: '#00ff88' }
                            },
                            y1: {
                                beginAtZero: true,
                                position: 'right',
                                ticks: { color: '#e0e6f0' },
                                grid: { drawOnChartArea: false },
                                title: { display: true, text: L('chart_exp', 'Exposure Mitigated (COP M)'), color: '#00bfff' }
                            },
                            x: {
                                ticks: { color: '#e0e6f0' },
                                grid: { color: 'rgba(255,255,255,0.05)' }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.reputationHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                crisisChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.reputationHistory },
                        { data: state.domainState.exposureHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var last = history[history.length - 1].results || {};
            var finalRep = last.reputation != null ? last.reputation : 0;
            var finalExp = last.exposureMitigated != null ? last.exposureMitigated : 0;
            var finalClients = last.clientsRetained != null ? last.clientsRetained : 0;
            var finalCash = last.cash != null ? last.cash : 0;
            var totalCorrect = history.reduce(function(s, r) { return s + ((r.results && r.results.diagnosisCorrect) ? 1 : 0); }, 0);
            var score = this._composite({ reputation: finalRep, exposureMitigated: finalExp, clientsRetained: finalClients });
            var perfKey = this._tierFor(score);
            var tt = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            var byRound = {};
            history.forEach(function(h) { if (h && h.results && h.results.period) byRound[h.results.period] = h.results; });
            var r1 = byRound[1] || {}, r2 = byRound[2] || {}, r3 = byRound[3] || {}, r4 = byRound[4] || {};

            /* Mistakes, in the order they were made; the first one is the turning point */
            var found = [];
            if (r1.primary) {
                if (!r1.diagnosisCorrect && r1.secondary === 'normal') found.push('ins_m_normal');
                else if (!r1.diagnosisCorrect) found.push('ins_m_wrongfamily');
                if (r1.communication === 'proactive') found.push('ins_m_early');
            }
            var silent = [r1, r2].filter(function(r) { return r.communication === 'internal'; }).length;
            if (silent > 0) found.push('ins_m_silence');
            if (r2.primary === 'patch') found.push('ins_m_patch');
            else if (r2.primary === 'defer') found.push('ins_m_defer');
            else if (r1.diagnosisCorrect && (r2.secondary === 'qq_only' || r2.secondary === 'none')) found.push('ins_m_novalid');
            if (r1.primary && !SFC_FLAGS[r1.primary]) found.push('ins_m_sfcopen');
            if (r3.primary === 'parallel_all') found.push('ins_m_parallel');
            else if (r3.primary === 'serial') found.push('ins_m_serial');
            else if (r3.primary === 'abandon_low') found.push('ins_m_abandon');
            if (r3.secondary === 'aggressive') found.push('ins_m_aggressive');
            else if (r3.secondary === 'contractor_only') found.push('ins_m_contractoronly');
            if (r4.secondary === 'no_change' || r4.primary === 'checklist' || r4.primary === 'external_audit') found.push('ins_m_weakreform');

            var turning = found.length ? tt(found[0]) : tt('ins_no_turning');
            var insights = [];
            for (var i = 1; i < found.length && insights.length < 3; i++) insights.push(tt(found[i]));
            if (finalRep < 50) insights.push(tt('ins_low_rep'));
            if (finalExp < 8000) insights.push(tt('ins_low_exp'));
            if (finalClients < 20) insights.push(tt('ins_lost_clients'));
            if (!found.length && finalRep >= 80 && finalExp >= 15000) insights.push(tt('ins_strong_turnaround'));
            if (!insights.length) insights.push(tt('ins_balanced'));
            insights = insights.slice(0, 5);

            return {
                totalExposureMitigated: finalExp,
                totalExposure: TOTAL_EXPOSURE,
                finalReputation: finalRep,
                finalClients: finalClients,
                finalCash: finalCash,
                correctDiagnoses: totalCorrect,
                performance: perfKey,
                performanceKey: perfKey,
                performanceLabel: tt(perfKey),
                mistakes: found,
                turningPoint: turning,
                questions: [tt('q_1'), tt('q_2'), tt('q_3')],
                insights: insights,
                composite: score,
                overallScore: score,
                totalScore: score,
                score: score
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var t = window.mySimulation.t.bind(window.mySimulation);
            if (results.notes && results.notes.length) {
                return results.notes.map(function(k) { return t(k); }).join(' ');
            }
            if (results.feedbackKey === 'fb_r1_wrong') return t('hint_r1_wrong');
            if (results.clientsDelta < 0) return t('hint_lost_client');
            if (results.repDelta < 0) return t('hint_reputation_drop');
            if (state.domainState.reputation < 50) return t('hint_low_rep');
            if (state.domainState.exposureMitigated > 15000) return t('hint_strong_progress');
            if (results.feedbackKey) return t(results.feedbackKey);
            return null;
        }

        getHistoryTableConfig() {
            var self = this;
            return [
                { key: 'results.period', label: 'Round', i18nKey: 'col_round' },
                { key: 'results.primary', label: 'Primary', i18nKey: 'col_primary',
                  formatter: function(v) { return self._labelFor('primary', v); } },
                { key: 'results.secondary', label: 'Secondary', i18nKey: 'col_secondary',
                  formatter: function(v) { return self._labelFor('secondary', v); } },
                { key: 'results.intensity', label: 'Intensity', i18nKey: 'col_intensity' },
                { key: 'results.reputation', label: 'Reputation', i18nKey: 'col_rep',
                  formatter: function(v) { return Math.round(v) + '/100'; } },
                { key: 'results.exposureMitigated', label: 'Exposure Mitigated', i18nKey: 'col_exp',
                  formatter: function(v) { return 'COP ' + Math.round(v).toLocaleString() + 'M'; } },
                { key: 'results.clientsRetained', label: 'Clients', i18nKey: 'col_clients',
                  formatter: function(v) { return v + '/23'; } }
            ];
        }

        _labelFor(kind, value) {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(x) { return x; };
            for (var round in ROUND_CONFIG) {
                var list = kind === 'primary' ? ROUND_CONFIG[round].primaryOptions : ROUND_CONFIG[round].secondaryOptions;
                for (var j = 0; j < list.length; j++) {
                    if (list[j].v === value) return t(list[j].k);
                }
            }
            return value;
        }

        getPresets() { return null; }

        _defaultDomainState() {
            return {
                cash: 14200,
                reputation: 75,
                exposureMitigated: 0,
                clientsRetained: 23,
                correctDiagnoses: 0,
                reputationHistory: [],
                exposureHistory: [],
                cashHistory: [],
                clientsHistory: []
            };
        }

        _wireFrameworkEvents() {
            if (this._wired) return;
            var sim = window.mySimulation;
            if (!sim || !sim.eventBus) return;
            var self = this;
            sim.eventBus.on('period:submitted', function() { self._onPeriodSubmitted(); });
            sim.eventBus.on('period:undone', function() { self._onPeriodUndone(); });
            document.addEventListener('express:langchanged', function() {
                try {
                    self._lastRenderedPeriod = 0;
                    self._updateBriefing(window.mySimulation.state);
                    self._renderHint();
                } catch (e) {}
            });
            this._wired = true;
        }

        _onPeriodSubmitted() {
            var sim = window.mySimulation;
            if (!sim || !sim.state) return;
            var live = sim.state.currentPeriod;
            // The framework advances currentPeriod AFTER grading. Render the NEW round
            // (briefing, labels, options) for the live period, guarded so we never render
            // past the final round or re-render a round we already drew.
            if (typeof live === 'number' && live > this._lastRenderedPeriod && live <= MAX_ROUNDS) {
                this._updateBriefing(sim.state);
            }
            this._renderHint();
        }

        _onPeriodUndone() {
            var sim = window.mySimulation;
            if (!sim || !sim.state) return;
            // Undoing the first round empties history; the framework's initialize() guard
            // will NOT reset a non-empty domainState, so reset it here to keep the KPI
            // displays consistent with an empty history.
            if (!sim.state.history || sim.state.history.length === 0) {
                sim.state.domainState = this._defaultDomainState();
                try { sim.updateUI(); } catch (e) {}
            }
            this._lastRenderedPeriod = 0;
            this._updateBriefing(sim.state);
            this._clearHint();
        }

        _renderHint() {
            var box = document.getElementById('hintBox');
            if (!box) return;
            var sim = window.mySimulation;
