        formatCompletionMessage(summary) {
            var t = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var s = summary || {};
            var rep = (s.finalReputation != null ? Math.round(s.finalReputation) : 0);
            var exp = (s.totalExposureMitigated != null ? s.totalExposureMitigated : 0);
            var total = (s.totalExposure != null ? s.totalExposure : TOTAL_EXPOSURE);
            var pct = total > 0 ? Math.round((exp / total) * 100) : 0;
            var clients = (s.finalClients != null ? s.finalClients : 0);
            var correct = (s.correctDiagnoses != null ? s.correctDiagnoses : 0);
            var cash = (s.finalCash != null ? Math.round(s.finalCash) : 0);
            var score = (s.overallScore != null ? s.overallScore : 0);
            var perf = s.performanceLabel || (s.performanceKey ? t(s.performanceKey) : '');
            var lang = (window.vcI18n && window.vcI18n._lang) || 'en';
            var loc = lang === 'es' ? 'es-CO' : 'en-US';
            var fmtCop = function(v) { return 'COP ' + Number(v).toLocaleString(loc) + 'M'; };
            var esc = function(x) { return String(x == null ? '' : x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
            var row = function(label, value) {
                return '<div style="display:flex;justify-content:space-between;gap:16px;padding:7px 2px;border-bottom:1px solid #e5e9f0;">' +
                    '<span style="color:#4b5563;">' + label + '</span>' +
                    '<span style="font-weight:700;color:#0b7a4b;">' + value + '</span></div>';
            };
            var list = function(items, ordered) {
                var tag = ordered ? 'ol' : 'ul';
                return '<' + tag + ' style="margin:6px 0 0 18px;padding:0;line-height:1.5;color:#333;">' +
                    (items || []).map(function(x) { return '<li style="margin:4px 0;">' + esc(x) + '</li>'; }).join('') + '</' + tag + '>';
            };
            var head = function(k) { return '<h5 style="margin:16px 0 4px;color:#0b3d2e;font-size:1rem;">' + t(k) + '</h5>'; };
            return '<div style="padding:8px 4px;text-align:left;max-width:520px;margin:0 auto;">' +
                '<h4 style="text-align:center;color:#0b7a4b;margin:0 0 16px;">' + t('summary_title') + '</h4>' +
                row(t('summary_score'), score + ' / 100') +
                row(t('summary_performance'), '<b>' + esc(perf) + '</b>') +
                row(t('summary_reputation'), rep + ' / 100') +
                row(t('summary_exposure'), fmtCop(exp) + ' (' + pct + '%)') +
                row(t('summary_clients'), clients + ' / 23') +
                row(t('summary_correct'), String(correct)) +
                row(t('summary_cash'), fmtCop(cash)) +
                head('summary_turning') +
                '<p style="margin:4px 0 0;line-height:1.55;color:#333;">' + esc(s.turningPoint || '') + '</p>' +
                head('summary_insights') + list(s.insights, false) +
                head('summary_questions') + list(s.questions, true) +
                '</div>';
        }

